partial class C1
{
    partial C1(int x);
    partial C1(ref int x) { }
}
partial class C2
{
    partial C2(in int x);
    partial C2(ref readonly int x) { }
}
partial class C3
{
    partial C3(ref int x);
    partial C3(out int x) => throw null;
}

